//! Helpers for writing checked-in generated files.

use std::fs;
use std::path::Path;

use anyhow::{bail, Context};

/// Prepends the header that marks `text` as generated by `cargo xtask {command}`.
pub(crate) fn add_preamble(command: &str, text: &str) -> String {
    format!("//! Generated by `cargo xtask {command}`, DO NOT EDIT BY HAND.\n{text}")
}

/// Ensures `path` contains `contents`, ignoring CRLF vs LF differences.
///
/// In `check` mode a mismatch is an error; otherwise the file is (re)written.
pub(crate) fn ensure_file_contents(
    command: &str,
    path: &Path,
    contents: &str,
    check: bool,
) -> anyhow::Result<()> {
    if let Ok(existing) = fs::read_to_string(path) {
        if normalize_newlines(&existing) == normalize_newlines(contents) {
            return Ok(());
        }
    }
    if check {
        bail!(
            "{} is not up to date; run `cargo xtask {command}` and commit the result",
            path.display()
        );
    }
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).with_context(|| format!("creating {}", parent.display()))?;
    }
    fs::write(path, contents).with_context(|| format!("writing {}", path.display()))?;
    eprintln!("updated {}", path.display());
    Ok(())
}

fn normalize_newlines(s: &str) -> String {
    s.replace("\r\n", "\n")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn stale_file_fails_in_check_mode() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("f.rs");
        fs::write(&path, "old\n").unwrap();
        let err = ensure_file_contents("cmd", &path, "new\n", true).unwrap_err();
        assert!(err
            .to_string()
            .contains("is not up to date; run `cargo xtask cmd`"));
        assert_eq!(fs::read_to_string(&path).unwrap(), "old\n");
    }

    #[test]
    fn missing_file_fails_in_check_mode() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("f.rs");
        assert!(ensure_file_contents("cmd", &path, "new\n", true).is_err());
        assert!(!path.exists());
    }

    #[test]
    fn stale_file_is_rewritten_in_write_mode() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("sub").join("f.rs");
        ensure_file_contents("cmd", &path, "new\n", false).unwrap();
        assert_eq!(fs::read_to_string(&path).unwrap(), "new\n");
    }

    #[test]
    fn crlf_only_difference_passes_check() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("f.rs");
        fs::write(&path, "a\r\nb\r\n").unwrap();
        ensure_file_contents("cmd", &path, "a\nb\n", true).unwrap();
    }

    #[test]
    fn preamble_names_command() {
        assert_eq!(
            add_preamble("cmd", "body\n"),
            "//! Generated by `cargo xtask cmd`, DO NOT EDIT BY HAND.\nbody\n"
        );
    }
}
